/// Сила «×соседи» в процентах из `strength_e2`; `-1` (соседей нет) — пусто.
/// Обратное — `read::strength_e2`.
fn strength_pct(e2: i64) -> String {
    if e2 < 0 {
        String::new()
    } else {
        format!("{}.{:02}", e2 / 100, e2 % 100)
    }
}

